using System.Windows;
using System.Windows.Controls;
using System.Text.RegularExpressions;
using DomainConsole.Shared;
namespace DomainConsole;
public sealed class UpdateConflictChoice:Window {
 public string Choice {get;private set;}="cancel";
 public UpdateConflictChoice(Window owner,string message,bool servicing){Owner=owner;Title="Windows Update · выбор действия";Width=620;SizeToContent=SizeToContent.Height;WindowStartupLocation=WindowStartupLocation.CenterOwner;var panel=new StackPanel{Margin=new(18)};Content=panel;panel.Children.Add(new TextBox{Text=message,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,MaxHeight=220,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new(0,0,0,12)});Add("Выполнить сейчас — несмотря на предупреждение","now");Add("Дождаться завершения обновлений", "wait");Add("Запросить остановку текущего задания", "stop");Add(servicing?"Запросить остановку обновлений и выполнить команду":"Остановить и повторить задание", "repeat");Add("Остановить и повторить с перезапуском выбранных служб…", "services");Add("Отмена", "cancel");void Add(string text,string value){var b=new Button{Content=text,Margin=new(0,3,0,3),Padding=new(9)};b.Click+=(s,e)=>{Choice=value;DialogResult=value!="cancel";};panel.Children.Add(b);}}
}
public sealed class ServiceRestartChoice:Window {
 public List<string> Services {get;}=new();public bool Force {get;private set;}
 public ServiceRestartChoice(Window owner){Owner=owner;Title="Перезапуск служб Windows Update";Width=520;SizeToContent=SizeToContent.Height;WindowStartupLocation=WindowStartupLocation.CenterOwner;var p=new StackPanel{Margin=new(18)};Content=p;p.Children.Add(new TextBlock{Text="Перезапуск прерывает работу выбранных служб. Кэш не очищается. Процессы TiWorker, TrustedInstaller и общий svchost не завершаются.",TextWrapping=TextWrapping.Wrap});var boxes=new Dictionary<string,CheckBox>();foreach(var name in new[]{"UsoSvc","wuauserv","bits","cryptsvc"}){var c=new CheckBox{Content=name,IsChecked=name=="UsoSvc",Margin=new(0,8,0,0)};boxes[name]=c;p.Children.Add(c);}var force=new CheckBox{Content="Принудительно: остановить зависимые службы",Margin=new(0,12,0,8),ToolTip="Stop-Service -Force. Операционная система всё равно может отказать или не остановить службу."};p.Children.Add(force);var b=new Button{Content="Применить к целям из следующего подтверждения",Padding=new(8)};b.Click+=(s,e)=>{Services.Clear();Services.AddRange(boxes.Where(x=>x.Value.IsChecked==true).Select(x=>x.Key));if(Services.Count==0)return;Force=force.IsChecked==true;DialogResult=true;};p.Children.Add(b);}}
public partial class MainWindow {
 public static bool NeedsUpdateCheck(IEnumerable<CommandStep> steps,bool microsoft)=>microsoft||steps.Any(s=>s.TouchesUpdates||s.Kind is "Updates" or "UpdateScan" or "CacheCleanup" or "ReportRecovery"||Regex.IsMatch(s.Code,@"(?i)\b(sfc|dism|Repair-WindowsImage)\b|(?:Stop-Service|Restart-Service|net\s+stop)\s+(?:wuauserv|bits|UsoSvc|cryptsvc)"));
 async Task<string> StopUpdatesFor(ComputerRow row){var ids=backgroundUpdates.TryGetValue(row.Host,out var live)?live.Jobs:new List<string>();ids=ids.Concat(History.Where(IsWsusJob).Where(j=>j.Targets.Any(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)&&t.Status is "Running" or "Submitted")).Select(j=>j.Id)).Distinct().ToList();if(ids.Count==0)return "Нет доступного задания DomainConsole для отмены. Внешней операцией Windows нельзя управлять через чужой объект WUA.";foreach(var id in ids)await remote.Cancel(row.Target,id,"now");var until=DateTime.UtcNow.AddSeconds(30);while(DateTime.UtcNow<until){bool running=false;foreach(var id in ids){var data=await remote.Poll(row.Target,id);running|=data.State==null||string.IsNullOrEmpty(data.State.Ended)||data.AgentAlive;}if(!running)return "";await Task.Delay(1000);}return "Запрос остановки отправлен, но завершение за 30 секунд не подтверждено.";}
 async Task<bool> PrepareUpdateAction(List<ComputerRow> rows,List<CommandStep> steps,bool microsoft){forceUpdateConflict=false;waitForUpdateConflict=false;if(!NeedsUpdateCheck(steps,microsoft))return true;Notify("Проверка активности Windows Update…");await HasLiveWsus(rows);var problems=rows.Where(r=>preflightErrors.ContainsKey(r.Host)||backgroundUpdates.TryGetValue(r.Host,out var live)&&(live.Busy||live.Jobs.Count>0||live.Limitation.Length>0||live.InstallationEvidence.Length>0)).ToList();if(problems.Count==0)return true;var message=string.Join("\n",problems.Select(r=>r.Name+": "+(preflightErrors.TryGetValue(r.Host,out var err)?"Состояние неизвестно: "+err:BackgroundText(r.Host,backgroundUpdates[r.Host])+"\n"+(backgroundUpdates[r.Host].Jobs.Count>0?"Есть активное задание DomainConsole.":""))))+"\n\nЕсли идёт установка, параллельное обслуживание может привести к ожиданию или ошибке занятости. Скачивание само по себе не означает установку. Ошибка диагностики не означает отказ подключения.";var dialog=new UpdateConflictChoice(this,message,steps.Any(s=>Regex.IsMatch(s.Code,@"(?i)\b(sfc|dism|Repair-WindowsImage)\b")));if(dialog.ShowDialog()!=true)return false;if(dialog.Choice=="wait"){waitForUpdateConflict=true;return true;}if(dialog.Choice=="now"){forceUpdateConflict=true;return true;}ServiceRestartChoice? restart=null;if(dialog.Choice=="services"){restart=new ServiceRestartChoice(this);if(restart.ShowDialog()!=true)return false;}
 foreach(var row in problems){string issue;try{issue=await StopUpdatesFor(row);}catch(Exception ex){issue="Остановка не подтверждена: "+ex.Message;}if(dialog.Choice=="stop"){Notify(row.Name+": "+(issue.Length>0?issue:"Задание завершилось после запроса остановки."));continue;}if(issue.Length>0&&MessageBox.Show(this,row.Name+": "+issue+"\nПродолжить выбранное действие несмотря на это?","Остановка не подтверждена",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return false;}if(dialog.Choice=="stop")return false;forceUpdateConflict=true;if(restart!=null)steps.Insert(0,new(){Name="Перезапуск выбранных служб Windows Update",Kind="PowerShell",TouchesUpdates=true,Code=RestartServicesScript(restart.Services,restart.Force)});return true;}
 bool forceUpdateConflict,waitForUpdateConflict;
 public static string RestartServicesScript(IEnumerable<string> services,bool force){var names=services.ToList();if(names.Count==0||names.Any(n=>n is not ("UsoSvc" or "wuauserv" or "bits" or "cryptsvc")))throw new ArgumentException("Неизвестная служба");return "$ErrorActionPreference='Stop';Add-Type -AssemblyName System.ServiceProcess;$names=@("+string.Join(",",names.Select(PowerShellBridge.Literal))+");$restore=New-Object 'System.Collections.Generic.HashSet[string]';function Save-Dependents($svc){foreach($dep in $svc.DependentServices){if($dep.Status -eq 'Running' -and $restore.Add($dep.ServiceName)){Save-Dependents $dep}}};if("+(force?"$true":"$false")+"){foreach($name in $names){Save-Dependents (Get-Service $name)}};try{foreach($name in $names){$svc=Get-Service $name;Write-Output ('Остановка: '+$name);Stop-Service $name "+(force?"-Force ":"")+"-ErrorAction Stop;$svc.WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::Stopped,[TimeSpan]::FromSeconds(20))}}finally{$errors=@();foreach($name in @($names)+@($restore)){try{Start-Service $name -ErrorAction Stop;(Get-Service $name).WaitForStatus([System.ServiceProcess.ServiceControllerStatus]::Running,[TimeSpan]::FromSeconds(20));Write-Output ('Запущена: '+$name)}catch{$errors+=($name+': '+$_.Exception.Message)}};if($errors.Count){throw ('Не восстановлены службы: '+($errors -join '; '))}};Get-Service $names|Select-Object Name,Status|Format-Table";}
 async void RestartServices_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var d=new ServiceRestartChoice(this);if(d.ShowDialog()!=true)return;MicrosoftBox.IsChecked=false;RebootBox.IsChecked=false;await Submit(new(){new(){Name="Перезапуск служб Windows Update",Kind="PowerShell",TouchesUpdates=true,Code=RestartServicesScript(d.Services,d.Force)}},"WSUS");});
}
